#!/usr/bin/env node
/**
 * Extracts the ABI array ONLY (not the full Hardhat artifact) from the compiled
 * Pingus2 artifact into `abi/Pingus2.json`. The web app imports that path, so
 * the file is committed to the repo and regenerated by `pnpm build`.
 */
const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const artifact = path.join(root, "artifacts", "contracts", "Pingus2.sol", "Pingus2.json");
const outDir = path.join(root, "abi");
const outFile = path.join(outDir, "Pingus2.json");

if (!fs.existsSync(artifact)) {
  console.error(`[extract-abi] artifact not found: ${artifact}\nRun \`hardhat compile\` first.`);
  process.exit(1);
}

const { abi } = JSON.parse(fs.readFileSync(artifact, "utf8"));
if (!Array.isArray(abi)) {
  console.error("[extract-abi] artifact has no abi array");
  process.exit(1);
}

fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(outFile, `${JSON.stringify(abi, null, 2)}\n`);

const fns = abi.filter((e) => e.type === "function").length;
const evts = abi.filter((e) => e.type === "event").length;
console.log(`[extract-abi] wrote abi/Pingus2.json — ${fns} functions, ${evts} events`);
